```typescript
export interface ParsedAgentId {
  publisherId?: string
  agentId?: string
  version?: string
}

export interface ParsedPublishedAgentId {
  publisherId: string
  agentId: string
  version?: string
}

export function parseAgentId(fullAgentId: string): ParsedAgentId {
  if (!fullAgentId || typeof fullAgentId !== 'string') {
    return {}
  }

  const parts = fullAgentId.split('/')

  if (parts.length === 2) {
    const [publisherId, agentNameWithVersion] = parts

    if (!publisherId || !agentNameWithVersion) {
      return {}
    }

    const versionMatch = agentNameWithVersion.match(/^(.+)@(.+)$/)
    if (versionMatch) {
      const [, agentId, version] = versionMatch
      return { publisherId, agentId, version }
    }

    return { publisherId, agentId: agentNameWithVersion }
  }

  if (parts.length === 1) {
    const agentNameWithVersion = parts[0]

    if (!agentNameWithVersion) {
      return {}
    }

    const versionMatch = agentNameWithVersion.match(/^(.+)@(.+)$/)
    if (versionMatch) {
      const [, agentId, version] = versionMatch
      return { agentId, version }
    }

    return { agentId: agentNameWithVersion }
  }

  return {}
}

export function parsePublishedAgentId(
  fullAgentId: string
): ParsedPublishedAgentId | null {
  if (!fullAgentId || typeof fullAgentId !== 'string') {
    return null
  }

  const parts = fullAgentId.split('/')
  if (parts.length !== 2) {
    return null
  }

  const [publisherId, agentNameWithVersion] = parts

  if (!publisherId || !agentNameWithVersion) {
    return null
  }

  const versionMatch = agentNameWithVersion.match(/^(.+)@(.+)$/)
  if (versionMatch) {
    const [, agentId, version] = versionMatch
    return { publisherId, agentId, version }
  }

  return { publisherId, agentId: agentNameWithVersion }
}
