Then add this new matching function after `parseAgentId`:

```typescript
/**
 * Match a child agent ID against spawnable agent patterns with flexible matching rules.
 * Returns the matching spawnable agent ID if found, null otherwise.
 * 
 * Matching rules:
 * - Agent name must always match
 * - Publisher matches if both specify it and they're equal, or if either doesn't specify it
 * - Version matches if both specify it and they're equal, or if either doesn't specify it
 */
export function findMatchingSpawnableAgent(
  childAgentId: string,
  spawnableAgents: string[],
): string | null {
  const childParsed = parseAgentId(childAgentId)
  if (!childParsed) {
    return null
  }

  for (const spawnableAgentId of spawnableAgents) {
    const spawnableParsed = parseAgentId(spawnableAgentId)
    if (!spawnableParsed) {
      continue
    }

    // Agent name must always match
    if (childParsed.agentId !== spawnableParsed.agentId) {
      continue
    }

    // Publisher matches if both don't have it OR both have it and they match
    const publisherMatches =
      !childParsed.publisherId ||
      !spawnableParsed.publisherId ||
      childParsed.publisherId === spawnableParsed.publisherId

    // Version matches if both don't have it OR both have it and they match
    const versionMatches =
      !childParsed.version ||
      !spawnableParsed.version ||
      childParsed.version === spawnableParsed.version

    if (publisherMatches && versionMatches) {
      return spawnableAgentId
    }
  }

  return null
}
```

