### 1. Backend API Enhancement

**File: `backend/src/api/agents.ts`**

Add authentication and display name support to the validation endpoint:

```typescript
import { AGENT_PERSONAS } from '@codebuff/common/constants/agents'
import { z } from 'zod/v4'

import { getAgentTemplate } from '../templates/agent-registry'
import { extractAuthTokenFromHeader } from '../util/auth-helpers'
import { logger } from '../util/logger'

import type {
  Request as ExpressRequest,
  Response as ExpressResponse,
  NextFunction,
} from 'express'

const AGENT_VALIDATION_CACHE_TTL_MS = 5 * 60 * 1000 // 5 minutes

type CacheEntry = {
  result: { valid: true; source?: string; normalizedId?: string; displayName?: string }
  expiresAt: number
}

const agentValidationCache = new Map<string, CacheEntry>()

const validateAgentRequestSchema = z.object({
  agentId: z.string().min(1),
})

export async function validateAgentNameHandler(
  req: ExpressRequest,
  res: ExpressResponse,
  next: NextFunction,
): Promise<void | ExpressResponse> {
  try {
    const apiKey = extractAuthTokenFromHeader(req)

    if (!apiKey) {
      return res.status(403).json({ error: 'API key required' })
    }

    const { agentId } = validateAgentRequestSchema.parse({
      agentId: String((req.query as any)?.agentId ?? ''),
    })

    const cached = agentValidationCache.get(agentId)
    if (cached && cached.expiresAt > Date.now()) {
      return res.status(200).json({ ...cached.result, cached: true })
    } else if (cached) {
      agentValidationCache.delete(agentId)
    }

    const builtInPersona = AGENT_PERSONAS[agentId as keyof typeof AGENT_PERSONAS]
    if (builtInPersona) {
      const result = {
        valid: true as const,
        source: 'builtin',
        normalizedId: agentId,
        displayName: builtInPersona.displayName,
      }
      agentValidationCache.set(agentId, {
        result,
        expiresAt: Date.now() + AGENT_VALIDATION_CACHE_TTL_MS,
      })
      return res.status(200).json(result)
    }

    const found = await getAgentTemplate(agentId, {})
    if (found) {
      const result = {
        valid: true as const,
        source: 'published',
        normalizedId: found.id,
        displayName: found.displayName,
      }
      agentValidationCache.set(agentId, {
        result,
        expiresAt: Date.now() + AGENT_VALIDATION_CACHE_TTL_MS,
      })
      return res.status(200).json(result)
    }

    return res.status(200).json({ valid: false })
  } catch (error) {
    logger.error(
      { error: error instanceof Error ? error.message : String(error) },
      'Error validating agent name',
    )
    if (error instanceof z.ZodError) {
      return res.status(400).json({
        valid: false,
        message: 'Invalid request',
        issues: error.issues,
      })
    }
    next(error)
    return
  }
}
```

**Changes:**
- Add API key check using `extractAuthTokenFromHeader(req)` at the start of the handler
- Return 403 with `{ error: 'API key required' }` when no API key is provided
- Update `CacheEntry` type to include optional `displayName` field
- Extract and include `displayName` from `AGENT_PERSONAS[agentId].displayName` for built-in agents
- Extract and include `displayName` from `found.displayName` for published agents
- Cache the `displayName` field for future requests

