**File: `backend/src/api/validate-agent-name.ts`**

```typescript
import { AGENT_PERSONAS } from '@codebuff/common/constants/agents'
import { getAgentTemplate } from '../templates/agent-registry'
import { z } from 'zod/v4'
import { logger } from '../util/logger'

import type {
  Request as ExpressRequest,
  Response as ExpressResponse,
  NextFunction,
} from 'express'

const validateAgentNameRequestSchema = z.object({
  agentId: z.string().min(1),
})

interface ValidationCache {
  result: {
    valid: true
    source: 'builtin' | 'published'
    normalizedId: string
  }
  timestamp: number
}

const validationCache = new Map<string, ValidationCache>()
const CACHE_TTL_MS = 5 * 60 * 1000

function getCachedValidation(agentId: string): ValidationCache['result'] | null {
  const cached = validationCache.get(agentId)
  if (!cached) return null

  const now = Date.now()
  if (now - cached.timestamp > CACHE_TTL_MS) {
    validationCache.delete(agentId)
    return null
  }

  return cached.result
}

function setCachedValidation(
  agentId: string,
  result: ValidationCache['result'],
): void {
  validationCache.set(agentId, {
    result,
    timestamp: Date.now(),
  })
}

async function validateAgentNameHandler(
  req: ExpressRequest,
  res: ExpressResponse,
  next: NextFunction,
): Promise<void | ExpressResponse> {
  const authHeader = req.headers.authorization
  const apiKey = req.headers['x-api-key']

  if (authHeader) {
    logger.debug('Authorization header present')
  }
  if (apiKey) {
    logger.debug('X-API-Key header present')
  }

  const parseResult = validateAgentNameRequestSchema.safeParse(req.query)

  if (!parseResult.success) {
    return res.status(400).json({
      valid: false,
      message: 'Invalid request',
      issues: parseResult.error.issues,
    })
  }

  const { agentId } = parseResult.data

  const cached = getCachedValidation(agentId)
  if (cached) {
    return res.status(200).json(cached)
  }

  if (agentId in AGENT_PERSONAS) {
    const result = {
      valid: true as const,
      source: 'builtin' as const,
      normalizedId: agentId,
    }
    setCachedValidation(agentId, result)
    return res.status(200).json(result)
  }

  const agentTemplate = await getAgentTemplate(agentId, {})

  if (agentTemplate) {
    const result = {
      valid: true as const,
      source: 'published' as const,
      normalizedId: agentTemplate.id,
    }
    setCachedValidation(agentId, result)
    return res.status(200).json(result)
  }

  return res.status(200).json({ valid: false })
}

export { validateAgentNameHandler }
