```typescript
import { API_KEY_ENV_VAR } from '@codebuff/common/constants'
import { red, yellow } from 'picocolors'

import { backendUrl } from '../config'
import { getUserCredentials } from '../credentials'
import { loadedAgents } from '../agents/load-agents'
import { logger } from './logger'
import { Spinner } from './spinner'

interface ValidationResponse {
  valid: boolean
  source?: 'builtin' | 'published'
  normalizedId?: string
  message?: string
}

export async function validateAgent(agentId: string): Promise<boolean> {
  if (loadedAgents[agentId]) {
    return true
  }

  const spinner = Spinner.get()
  spinner.start('Checking agent...')

  const user = getUserCredentials()
  const headers: Record<string, string> = {}

  if (user?.authToken) {
    headers['Authorization'] = `Bearer ${user.authToken}`
    logger.debug('Using user auth token for agent validation')
  }

  const apiKey = process.env[API_KEY_ENV_VAR]
  if (apiKey) {
    headers['X-API-Key'] = apiKey
    logger.debug('Using API key for agent validation')
  }

  if (!user?.authToken && !apiKey) {
    logger.debug('No credentials available for agent validation')
  }

  const url = `${backendUrl}/api/agents/validate-name?agentId=${encodeURIComponent(agentId)}`

  const response = await fetch(url, {
    method: 'GET',
    headers,
  }).catch((error) => {
    spinner.stop()

    const errorMessage = error instanceof Error ? error.message : String(error)
    console.warn(
      yellow(
        `Warning: Could not validate agent "${agentId}": ${errorMessage}. Continuing anyway...`,
      ),
    )
    logger.warn(
      {
        agentId,
        errorMessage,
        errorStack: error instanceof Error ? error.stack : undefined,
      },
      'Network error during agent validation',
    )

    return null
  })

  spinner.stop()

  if (!response) {
    return true
  }

  if (!response.ok) {
    const errorData: ValidationResponse = await response.json().catch(() => ({
      valid: false,
      message: `HTTP ${response.status}: ${response.statusText}`,
    }))

    console.error(
      red(
        `Invalid agent: "${agentId}". ${errorData.message || 'Agent not found.'}`,
      ),
    )
    process.exit(1)
  }

  const data: ValidationResponse = await response.json()

  if (!data.valid) {
    console.error(red(`Invalid agent: "${agentId}". Agent not found.`))
    process.exit(1)
  }

  return true
}
```

