```typescript
import { spawn } from 'child_process'
import { platform } from 'os'

const IS_WINDOWS = platform() === 'win32'

export async function runTerminalCommand(
  command: string,
  processType: string,
  cwd: string,
  timeoutSeconds: number,
): Promise<string> {
  if (processType === 'BACKGROUND') {
    throw new Error(
      'BACKGROUND process type is not supported. Only SYNC commands are allowed.',
    )
  }

  const shell = IS_WINDOWS ? 'cmd.exe' : 'bash'
  const shellArgs = IS_WINDOWS ? ['/c', command] : ['-c', command]

  const env = {
    ...process.env,
    FORCE_COLOR: '3',
    CLICOLOR: '1',
    CLICOLOR_FORCE: '1',
  }

  return new Promise((resolve) => {
    let stdout = ''
    let stderr = ''
    let timedOut = false

    const child = spawn(shell, shellArgs, { cwd, env })

    const timeoutHandle =
      timeoutSeconds < 0
        ? null
        : setTimeout(() => {
            timedOut = true
            child.kill('SIGTERM')
          }, timeoutSeconds * 1000)

    child.stdout.on('data', (data) => {
      stdout += data.toString()
    })

    child.stderr.on('data', (data) => {
      stderr += data.toString()
    })

    child.on('error', (error) => {
      if (timeoutHandle) clearTimeout(timeoutHandle)
      resolve(formatOutput(stdout, stderr, null, `Failed to spawn process: ${error.message}`))
    })

    child.on('close', (exitCode) => {
      if (timeoutHandle) clearTimeout(timeoutHandle)
      const errorMessage = timedOut ? 'Command timed out' : null
      resolve(formatOutput(stdout, stderr, exitCode, errorMessage))
    })
  })
}

function formatOutput(
  stdout: string,
  stderr: string,
  exitCode: number | null,
  errorMessage: string | null,
): string {
  let result = ''

  if (stdout) {
    result += `# stdout\n\`\`\`\n${stdout}\n\`\`\`\n\n`
  }

  if (stderr) {
    result += `# stderr\n\`\`\`\n${stderr}\n\`\`\`\n\n`
  }

  if (exitCode !== null) {
    result += `# exit_code\n\`\`\`\n${exitCode}\n\`\`\`\n`
  }

  if (errorMessage) {
    result += `# error\n\`\`\`\n${errorMessage}\n\`\`\`\n`
  }

  return result.trim()
}
```

