Add the new resolution function:

```typescript
export const DEFAULT_ORG_PREFIX = 'CodebuffAI/'

/**
 * Resolves CLI agent IDs with the following logic:
 * - Returns undefined if input is undefined
 * - Preserves explicitly prefixed identifiers (containing '/') as-is
 * - Returns input as-is if it exists in local agent IDs
 * - Applies DEFAULT_ORG_PREFIX to unprefixed identifiers not found locally
 */
export function resolveCliAgentId(
  input: string | undefined,
  localAgentIds: string[],
): string | undefined {
  if (input === undefined) {
    return undefined
  }

  if (input.includes('/')) {
    return input
  }

  if (localAgentIds.includes(input)) {
    return input
  }

  return `${DEFAULT_ORG_PREFIX}${input}`
}
```

