```typescript
import * as fs from 'fs'
import * as path from 'path'

interface AgentWithMetadata {
  id: string
  name: string
  description?: string
  isBuiltIn: boolean
  filePath?: string
  modifiedTime?: number
  agentDefinition?: any
}

function getFileModifiedTime(filePath: string): number {
  try {
    const stats = fs.statSync(filePath)
    return stats.mtimeMs
  } catch {
    return 0
  }
}

async function loadAgentDefinition(filePath: string): Promise<any | null> {
  try {
    const agentModule = await require(filePath)
    delete require.cache[filePath]
    return agentModule.default || null
  } catch {
    return null
  }
}

function isRecentlyModified(modifiedTime: number): boolean {
  const sevenDaysInMs = 7 * 24 * 60 * 60 * 1000
  return Date.now() - modifiedTime < sevenDaysInMs
}

export async function enterAgentsBuffer(rl: any, onExit: () => void) {
  if (isInAgentsBuffer) {
    console.log(yellow('Already in agents mode!'))
    return
  }

  await loadLocalAgents({ verbose: false })
  const localAgents = getLoadedAgentNames()

  const actions: typeof agentList = [
    {
      id: '__header__',
      name: bold(cyan('Actions')),
      description: '',
      isBuiltIn: false,
      isSectionHeader: true,
    },
    {
      id: '__create_new__',
      name: '+ Create New Agent',
      description: 'Create a new custom agent template',
      isBuiltIn: false,
      isCreateNew: true,
    },
  ]

  const agentsDir = path.join(getProjectRoot(), AGENT_TEMPLATES_DIR)
  const agentsWithMetadata: AgentWithMetadata[] = []

  if (fs.existsSync(agentsDir)) {
    const files = fs.readdirSync(agentsDir)
    const customAgentFiles = filterCustomAgentFiles(files)

    for (const file of customAgentFiles) {
      const filePath = path.join(agentsDir, file)
      const agentId = extractAgentIdFromFileName(file)
      const modifiedTime = getFileModifiedTime(filePath)
      const agentDefinition = await loadAgentDefinition(filePath)

      // Filter: only include agents with valid id and model
      if (!agentDefinition?.id || !agentDefinition?.model) {
        continue
      }

      const displayName = agentDefinition.displayName || localAgents[agentId] || agentId
      const description = agentDefinition.spawnerPrompt || agentDefinition.systemPrompt?.slice(0, 100) || 'Custom user-defined agent'

      agentsWithMetadata.push({
        id: agentId,
        name: displayName,
        description,
        isBuiltIn: false,
        filePath,
        modifiedTime,
        agentDefinition,
      })
    }
  }

  // Sort by modification time (newest first)
  agentsWithMetadata.sort((a, b) => (b.modifiedTime || 0) - (a.modifiedTime || 0))

  // Group by recency
  const recentAgents = agentsWithMetadata.filter(agent => 
    isRecentlyModified(agent.modifiedTime || 0)
  )
  const olderAgents = agentsWithMetadata.filter(agent => 
    !isRecentlyModified(agent.modifiedTime || 0)
  )

  agentList = [...actions]

  // Add "Recently Updated" section
  if (recentAgents.length > 0) {
    agentList.push({
      id: '__recent_header__',
      name: bold(cyan('Recently Updated')) + gray(` • ${recentAgents.length} in ${AGENT_TEMPLATES_DIR}`),
      description: '',
      isBuiltIn: false,
      isSectionHeader: true,
    })

    for (const agent of recentAgents) {
      agentList.push({
        id: agent.id,
        name: agent.name,
        description: agent.description,
        isBuiltIn: false,
        filePath: agent.filePath,
      })
    }
  }

  // Add "Custom Agents" section
  if (olderAgents.length > 0) {
    agentList.push({
      id: '__agents_header__',
      name: bold(cyan('Custom Agents')) + gray(` • ${olderAgents.length} in ${AGENT_TEMPLATES_DIR}`),
      description: '',
      isBuiltIn: false,
      isSectionHeader: true,
    })

    for (const agent of olderAgents) {
      agentList.push({
        id: agent.id,
        name: agent.name,
        description: agent.description,
        isBuiltIn: false,
        filePath: agent.filePath,
      })
    }
  }

  // If no agents at all, add placeholder
  if (agentsWithMetadata.length === 0) {
    agentList.push({
      id: '__agents_header__',
      name: bold(cyan('Custom Agents')) + gray(` • 0 in ${AGENT_TEMPLATES_DIR}`),
      description: '',
      isBuiltIn: false,
      isSectionHeader: true,
    })

    agentList.push({
      id: '__no_agents__',
      name: gray('No custom agents found'),
      description: 'Use "Create New Agent" above to get started',
      isBuiltIn: false,
      isPlaceholder: true,
    })
  }

  // ... rest of existing code for rendering ...
}
