### Phase 2: Create REST API Validation Endpoint

#### File: `web/src/app/api/agents/validate/route.ts` (new file)

```typescript
import { validateAgents } from '@codebuff/common/templates/agent-validation'
import { checkAuthToken } from '@codebuff/internal'
import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'

import type { NextRequest } from 'next/server'

import { authOptions } from '../../auth/[...nextauth]/auth-options'
import { logger } from '@/util/logger'

interface ValidateAgentsRequest {
  agentConfigs: Record<string, any>
}

export async function POST(request: NextRequest) {
  let userId: string | undefined
  const session = await getServerSession(authOptions)

  if (session?.user?.id) {
    userId = session.user.id
  } else {
    const authToken = request.cookies.get('next-auth.session-token')?.value
    if (authToken) {
      const authResult = await checkAuthToken({ authToken })
      if (authResult.success && authResult.user) {
        userId = authResult.user.id
      }
    }
  }

  if (!userId) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  let body: ValidateAgentsRequest
  try {
    body = await request.json()
  } catch (error) {
    return NextResponse.json(
      { error: 'Invalid JSON in request body' },
      { status: 400 }
    )
  }

  const { agentConfigs } = body

  if (!agentConfigs || typeof agentConfigs !== 'object') {
    return NextResponse.json(
      { error: 'agentConfigs must be an object' },
      { status: 400 }
    )
  }

  const { templates, validationErrors } = validateAgents(agentConfigs)

  logger.info(
    {
      userId,
      agentCount: Object.keys(agentConfigs).length,
      validCount: Object.keys(templates).length,
      errorCount: validationErrors.length,
    },
    'Agent validation request processed'
  )

  return NextResponse.json({
    valid: validationErrors.length === 0,
    templates: Object.keys(templates),
    validationErrors,
  })
}
```

### Phase 3: Create Client-Side Validation Utility

#### File: `npm-app/src/agents/validate-agents-client.ts` (new file)

```typescript
import { backendUrl } from '../config'
import { Client } from '../client'
import { logger } from '../utils/logger'
import { yellow, red } from 'picocolors'

export async function validateAgentsClient(): Promise<void> {
  const client = Client.getInstance(false)

  if (!client || !client.user || !client.user.authToken) {
    return
  }

  const fileContext = client.fileContext
  if (!fileContext || !fileContext.agentTemplates) {
    return
  }

  const agentConfigs = fileContext.agentTemplates

  if (Object.keys(agentConfigs).length === 0) {
    return
  }

  try {
    const response = await fetch(`${backendUrl}/api/agents/validate`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${client.user.authToken}`,
      },
      body: JSON.stringify({ agentConfigs }),
    })

    if (!response.ok) {
      return
    }

    const result = await response.json()

    if (result.validationErrors && result.validationErrors.length > 0) {
      console.log(yellow('\n⚠️  Agent Configuration Warnings:'))
      for (const error of result.validationErrors) {
        console.log(red(`  • ${error.filePath}: ${error.message}`))
      }
      console.log()
    }
  } catch (error) {
    logger.debug(
      {
        errorMessage: error instanceof Error ? error.message : String(error),
        errorStack: error instanceof Error ? error.stack : undefined,
      },
      'Agent validation request failed',
    )
  }
}
```

