### 6. Implement Tool Handler

**File: `backend/src/tools/handlers/tool/spawn-agent-inline.ts`** (new file)

```typescript
import { generateCompactId } from '@codebuff/common/util/string'

import { getAgentTemplate } from '../../../templates/agent-registry'
import { logger } from '../../../util/logger'
import { expireMessages } from '../../../util/messages'

import type { AgentState, AgentTemplateType } from '@codebuff/common/types/session-state'
import type { CodebuffToolHandlerFunction } from '../handler-function-type'

export const handleSpawnAgentInline: CodebuffToolHandlerFunction<'spawn_agent_inline'> = ({
  previousToolCallFinished,
  toolCall,
  fileContext,
  clientSessionId,
  userInputId,
  state,
}) => {
  const { agent_type: agentTypeStr, prompt, params: childParams } = toolCall.args
  const {
    ws,
    fingerprintId,
    userId,
    agentTemplate: parentAgentTemplate,
    localAgentTemplates,
    messages,
  } = state
  let { agentState } = state

  if (!ws || !fingerprintId || !parentAgentTemplate || !messages || !agentState || !localAgentTemplates) {
    throw new Error('Internal error for spawn_agent_inline: Missing required state')
  }

  const triggerSpawnAgentInline = async () => {
    const agentType = agentTypeStr as AgentTemplateType
    const agentTemplate = await getAgentTemplate(agentType, localAgentTemplates)

    if (!agentTemplate) {
      throw new Error(`Agent type ${agentTypeStr} not found.`)
    }

    if (!parentAgentTemplate.subagents.includes(agentType)) {
      throw new Error(
        `Agent type ${parentAgentTemplate.id} is not allowed to spawn child agent type ${agentType}.`,
      )
    }

    // Validate prompt and params against agent's schema
    const { inputSchema } = agentTemplate

    if (inputSchema.prompt) {
      const result = inputSchema.prompt.safeParse(prompt)
      if (!result.success) {
        throw new Error(
          `Invalid prompt for agent ${agentType}: ${JSON.stringify(result.error.issues, null, 2)}`,
        )
      }
    }

    if (inputSchema.params) {
      const result = inputSchema.params.safeParse(childParams)
      if (!result.success) {
        throw new Error(
          `Invalid params for agent ${agentType}: ${JSON.stringify(result.error.issues, null, 2)}`,
        )
      }
    }

    const childAgentId = generateCompactId()

    // Create child agent state that shares the same message history
    const childAgentState: AgentState = {
      agentId: childAgentId,
      agentType,
      agentContext: agentState!.agentContext,
      subagents: [],
      messageHistory: messages,
      stepsRemaining: 20,
      output: undefined,
      parentId: agentState!.agentId,
    }

    logger.debug(
      {
        agentTemplate,
        prompt,
        params: childParams,
        agentId: childAgentId,
        parentId: childAgentState.parentId,
      },
      `Spawning inline agent — ${agentType} (${childAgentId})`,
    )

    // Import loopAgentSteps dynamically to avoid circular dependency
    const { loopAgentSteps } = await import('../../../run-agent-step')

    await loopAgentSteps(ws, {
      userInputId: `${userInputId}-${agentType}${childAgentId}`,
      prompt: prompt || '',
      params: childParams,
      agentType: agentTemplate.id,
      agentState: childAgentState,
      fingerprintId,
      fileContext,
      localAgentTemplates,
      toolResults: [],
      userId,
      clientSessionId,
      onResponseChunk: () => {},
    })

    // Expire messages with timeToLive: 'userPrompt'
    const cleanedMessages = expireMessages(messages, 'userPrompt')

    // Update parent agent's message history with the final shared state
    agentState!.messageHistory = cleanedMessages
    state.messages = cleanedMessages
  }

  previousToolCallFinished.then(triggerSpawnAgentInline)

  return {
    result: undefined,
    state: {},
  }
}
```

