/**
 * Codebuff Agent Type Definitions
 *
 * This file provides TypeScript type definitions for creating custom Codebuff agents.
 * Import these types in your agent files to get full type safety and IntelliSense.
 */

// ============================================================================
// Core Agent Configuration Types
// ============================================================================

/**
 * Configuration for a Codebuff agent
 */
export interface AgentConfig {
  /** Unique identifier for this agent. Must contain only lowercase letters, numbers, and hyphens */
  id: string

  /** Version string (defaults to '0.0.1' and bumps on each publish) */
  version?: string

  /** Publisher ID for the agent (required for publishing) */
  publisher?: string

  /** Human-readable name for the agent */
  displayName: string

  /** AI model to use for this agent. See https://openrouter.ai/models */
  model: ModelName

  /** Tools this agent can use */
  toolNames?: ToolName[]

  /** Other agents this agent can spawn */
  subagents?: SubagentName[]

  /** Input schema for spawning the agent */
  inputSchema?: {
    prompt?: { type: 'string'; description?: string }
    params?: JsonSchema
  }

  /** Whether to include conversation history from parent agent (defaults to false) */
  includeMessageHistory?: boolean

  /** How the agent outputs responses: 'last_message' | 'all_messages' | 'json' */
  outputMode?: 'last_message' | 'all_messages' | 'json'

  /** JSON schema for structured output (when outputMode is 'json') */
  outputSchema?: JsonSchema

  /** Prompt for when to spawn this agent as a subagent */
  parentPrompt?: string

  /** Background information for the agent */
  systemPrompt?: string

  /** Instructions for the agent (inserted after each user input) */
  instructionsPrompt?: string

  /** Prompt inserted at each agent step */
  stepPrompt?: string

  /** Programmatically step the agent forward and run tools */
  handleSteps?: (
    context: AgentStepContext,
  ) => Generator<
    ToolCall | 'STEP' | 'STEP_ALL',
    void,
    { agentState: AgentState; toolResult: ToolResult | undefined }
  >
}

// ============================================================================
// Supporting Types
// ============================================================================

export interface AgentState {
  agentId: string
  parentId: string
  messageHistory: Message[]
}

export interface Message {
  role: 'user' | 'assistant' | 'system'
  content: string | MessageContentObject[]
  timestamp?: number
}

export type MessageContentObject =
  | { type: 'text'; text: string }
  | { type: 'tool_use'; id: string; name: string; input: Record<string, any> }
  | { type: 'tool_result'; tool_use_id: string; content: string }
  | { type: 'image'; source: { type: 'base64'; media_type: 'image/jpeg'; data: string } }

export interface AgentStepContext {
  agentState: AgentState
  prompt?: string
  params?: Record<string, any>
}

export type ToolCall<T extends ToolName = ToolName> = {
  [K in T]: {
    toolName: K
    args?: Tools.GetToolParams<K>
  }
}[T]

export interface ToolResult {
  toolName: string
  toolCallId: string
  result: string
}

export interface JsonSchema {
  type: string
  description?: string
  properties?: Record<string, any>
  required?: string[]
  [key: string]: any
}

// ============================================================================
// Available Tools by Category
