**File: `sdk/src/tools/read-files.ts`** (new file)

```typescript
import fs from 'fs'
import path from 'path'
import { FILE_READ_STATUS } from '../../../common/src/constants'

export function getFiles(
  filePaths: string[],
  cwd: string,
): Record<string, string | null> {
  const result: Record<string, string | null> = {}
  const MAX_FILE_SIZE = 1024 * 1024

  for (const filePath of filePaths) {
    if (!filePath) {
      continue
    }

    const absolutePath = path.isAbsolute(filePath)
      ? filePath
      : path.join(cwd, filePath)
    const resolvedPath = path.resolve(absolutePath)
    const resolvedCwd = path.resolve(cwd)

    if (!resolvedPath.startsWith(resolvedCwd)) {
      result[filePath] = FILE_READ_STATUS.OUTSIDE_PROJECT
      continue
    }

    const relativePath = path.isAbsolute(filePath)
      ? path.relative(resolvedCwd, resolvedPath)
      : filePath

    try {
      const stats = fs.statSync(resolvedPath)
      if (stats.size > MAX_FILE_SIZE) {
        const sizeMB = (stats.size / (1024 * 1024)).toFixed(2)
        result[relativePath] = `${FILE_READ_STATUS.TOO_LARGE} (${sizeMB} MB)`
      } else {
        result[relativePath] = fs.readFileSync(resolvedPath, 'utf8')
      }
    } catch (error) {
      if (
        error &&
        typeof error === 'object' &&
        'code' in error &&
        error.code === 'ENOENT'
      ) {
        result[relativePath] = FILE_READ_STATUS.DOES_NOT_EXIST
      } else {
        result[relativePath] = FILE_READ_STATUS.ERROR
      }
    }
  }

  return result
}
```

**Key features:**
- Skips empty/null paths with early continue
- Resolves paths and checks security before any file operations
- Converts absolute paths within project to relative paths
- Checks file size before reading (1MB limit)
- Returns file content for successful reads, status messages for errors
- Handles ENOENT specifically, other errors generically

