#### 4.4 Create `sdk/src/websocket-handler.ts`

Create a new WebSocketHandler class:

```typescript
import { WebSocket } from 'ws'
import { WEBSOCKET_URL } from './constants'

type ServerAction = {
  type: string
  [key: string]: any
}

type ClientAction = {
  type: string
  [key: string]: any
}

type ServerMessage =
  | { type: 'action'; data: ServerAction }
  | { type: 'ack'; txid?: number; error?: string }

type WebSocketHandlerOptions = {
  url?: string
  onError?: (event: WebSocket.ErrorEvent) => void
  onReconnect?: () => void
  onOpen?: () => void
  onClose?: (code: number, reason: string) => void
}

export class WebSocketHandler {
  private ws!: WebSocket
  private url: string
  private subscribers: Map<string, ((action: ServerAction) => void)[]>
  private txid: number
  private txns: Map<number, { resolve: () => void; reject: (err: Error) => void; timeout?: any }>
  private connectTimeout?: any
  private heartbeat?: any
  private hadError = false
  private onError?: (event: WebSocket.ErrorEvent) => void
  private onReconnect?: () => void
  private onOpen?: () => void
  private onClose?: (code: number, reason: string) => void

  constructor(options: WebSocketHandlerOptions = {}) {
    this.url = options.url ?? WEBSOCKET_URL
    this.txid = 0
    this.txns = new Map()
    this.subscribers = new Map()
    this.onError = options.onError
    this.onReconnect = options.onReconnect
    this.onOpen = options.onOpen
    this.onClose = options.onClose
  }

  get readyState() {
    return this.ws?.readyState
  }

  async connect() {
    this.ws = new WebSocket(this.url)

    this.ws.onmessage = (ev) => {
      if (this.hadError) {
        this.hadError = false
        this.onReconnect?.()
      }
      this.receiveMessage(JSON.parse(ev.data as any))
    }

    this.ws.onerror = (ev) => {
      if (!this.hadError) {
        this.onError?.(ev)
        this.hadError = true
      }
      this.waitAndReconnect()
    }

    this.ws.onclose = (ev) => {
      clearInterval(this.heartbeat)
      this.onClose?.(ev.code, ev.reason)

      for (const txn of Array.from(this.txns.values())) {
        clearTimeout(txn.timeout)
        txn.resolve()
      }
      this.txns.clear()

      if (ev.code !== 1000) {
        this.waitAndReconnect()
      }
    }

    return new Promise<void>((resolve) => {
      this.ws.onopen = () => {
        this.heartbeat = setInterval(
          async () => this.sendMessage('ping', {}).catch(() => {}),
          30000,
        )
        this.onOpen?.()
        resolve()
      }
    })
  }

  close() {
    this.ws?.close(1000, 'Closed manually.')
    clearTimeout(this.connectTimeout)
  }

  private waitAndReconnect() {
    if (this.connectTimeout == null) {
      this.connectTimeout = setTimeout(() => {
        this.connectTimeout = undefined
        this.connect()
      }, 5000)
    }
  }

  private receiveMessage(msg: ServerMessage) {
    switch (msg.type) {
      case 'action': {
        const action = msg.data
        const subscribers = this.subscribers.get(action.type) ?? []
        for (const callback of subscribers) {
          callback(action)
        }
        return
      }
      case 'ack': {
        if (msg.txid != null) {
          const txn = this.txns.get(msg.txid)
          if (txn) {
            clearTimeout(txn.timeout)
            if (msg.error != null) {
              txn.reject(new Error(msg.error))
            } else {
              txn.resolve()
            }
            this.txns.delete(msg.txid)
          }
        }
        return
      }
    }
  }

  async sendMessage(type: string, data: Record<string, any>) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      return new Promise<void>((resolve, reject) => {
        const txid = this.txid++
        const timeout = setTimeout(() => {
          this.txns.delete(txid)
          reject(new Error(`Message with txid ${txid} timed out.`))
        }, 120000)
        this.txns.set(txid, { resolve, reject, timeout })
        this.ws.send(JSON.stringify({ type, txid, ...data }))
      })
    }
  }

  async sendAction(action: ClientAction) {
    return this.sendMessage('action', { data: action })
  }

  subscribe<T extends string>(
    actionType: T,
    callback: (action: ServerAction) => void,
  ) {
    const currSubscribers = this.subscribers.get(actionType) ?? []
    this.subscribers.set(actionType, [...currSubscribers, callback])

    return () => {
      const newSubscribers = currSubscribers.filter((cb) => cb !== callback)
      this.subscribers.set(actionType, newSubscribers)
    }
  }
}
