```typescript
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useSession } from 'next-auth/react'
import { useEffect } from 'react'

import type { UserProfile } from '@/types/user'

const STORAGE_KEY = 'userProfile'

function getStoredProfile(): UserProfile | null {
  if (typeof window === 'undefined') return null

  const stored = localStorage.getItem(STORAGE_KEY)
  if (!stored) return null

  const parsed = JSON.parse(stored)
  return {
    ...parsed,
    created_at: parsed.created_at ? new Date(parsed.created_at) : null,
  }
}

function setStoredProfile(profile: UserProfile): void {
  if (typeof window === 'undefined') return

  const serialized = JSON.stringify({
    ...profile,
    created_at: profile.created_at?.toISOString() ?? null,
  })
  localStorage.setItem(STORAGE_KEY, serialized)
}

function clearStoredProfile(): void {
  if (typeof window === 'undefined') return
  localStorage.removeItem(STORAGE_KEY)
}

async function fetchUserProfile(): Promise<UserProfile> {
  const response = await fetch('/api/user/profile')
  if (!response.ok) throw new Error('Failed to fetch user profile')

  const data = await response.json()
  return {
    ...data,
    created_at: data.created_at ? new Date(data.created_at) : null,
  }
}

export function useUserProfile() {
  const { status } = useSession()
  const queryClient = useQueryClient()
  const isAuthenticated = status === 'authenticated'

  const { data: userProfile, isLoading } = useQuery({
    queryKey: ['userProfile'],
    queryFn: fetchUserProfile,
    enabled: isAuthenticated,
    initialData: () => getStoredProfile() ?? undefined,
    staleTime: 1000 * 60 * 5,
  })

  useEffect(() => {
    if (userProfile) {
      setStoredProfile(userProfile)
    }
  }, [userProfile])

  useEffect(() => {
    if (status === 'unauthenticated') {
      clearStoredProfile()
      queryClient.removeQueries({ queryKey: ['userProfile'] })
    }
  }, [status, queryClient])

  const clearCache = () => {
    clearStoredProfile()
    queryClient.removeQueries({ queryKey: ['userProfile'] })
  }

  return {
    userProfile: userProfile ?? null,
    isLoading,
    clearCache,
  }
}
```

