// Add this helper function near the top
function getAgentContext(agentId: string, displayName?: string): string {
  if (displayName) {
    return `Agent "${agentId}" (${displayName})`
  }
  return `Agent "${agentId}"`
}

// Update validateAgents signature
export function validateAgents(
  agentTemplates: Record<string, any> = {},
): {
  templates: Record<string, AgentTemplate>
  validationErrors: DynamicAgentValidationError[]
} {
  const templates: Record<string, AgentTemplate> = {}
  const validationErrors: DynamicAgentValidationError[] = []

  const hasAgentTemplates = Object.keys(agentTemplates).length > 0

  if (!hasAgentTemplates) {
    return {
      templates,
      validationErrors,
    }
  }

  const agentKeys = Object.keys(agentTemplates)
  const dynamicAgentIds = collectAgentIds(agentTemplates)

  for (const agentKey of agentKeys) {
    try {
      const content = agentTemplates[agentKey]
      if (!content) {
        continue
      }

      const validationResult = validateSingleAgent(content, {
        filePath: agentKey,
        dynamicAgentIds,
      })

      if (!validationResult.success) {
        validationErrors.push({
          filePath: agentKey,
          message: validationResult.error!,
        })
        continue
      }

      if (templates[content.id]) {
        const agentContext = getAgentContext(content.id, content.displayName)
        validationErrors.push({
          filePath: agentKey,
          message: `${agentContext}: Duplicate agent ID`,
        })
        continue
      }
      templates[content.id] = validationResult.agentTemplate!
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Unknown error'

      const agentId = agentTemplates[agentKey]?.id || agentKey
      const displayName = agentTemplates[agentKey]?.displayName
      const agentContext = getAgentContext(agentId, displayName)

      validationErrors.push({
        filePath: agentKey,
        message: `${agentContext}: ${errorMessage}`,
      })

      logger.warn(
        { filePath: agentKey, error: errorMessage },
        'Failed to load dynamic agent template',
      )
    }
  }

  return {
    templates,
    validationErrors,
  }
}

// Update collectAgentIds signature
export function collectAgentIds(
  agentTemplates: Record<string, any> = {},
): string[] {
  const agentIds: string[] = []
  const jsonFiles = Object.keys(agentTemplates)

  for (const filePath of jsonFiles) {
    try {
      const content = agentTemplates[filePath]
      if (!content) {
        continue
      }

      if (content.id && typeof content.id === 'string') {
        agentIds.push(content.id)
      }
    } catch (error) {
      logger.debug(
        { filePath, error },
        'Failed to extract agent ID during collection phase',
      )
    }
  }

  return agentIds
}

// Update validateSingleAgent with early schema validation and enhanced error messages
export function validateSingleAgent(
  template: any,
  options?: {
    dynamicAgentIds?: string[]
    filePath?: string
    skipSubagentValidation?: boolean
  },
): {
  success: boolean
  agentTemplate?: AgentTemplate
  error?: string
} {
  const {
    filePath,
    skipSubagentValidation = true,
    dynamicAgentIds = [],
  } = options || {}

  try {
    const agentId = template?.id || 'unknown'
    const displayName = template?.displayName
    const agentContext = getAgentContext(agentId, displayName)

    // Early schema validation
    let validatedTemplate: any
    if (template.handleSteps && typeof template.handleSteps === 'string') {
      const configResult = DynamicAgentTemplateSchema.safeParse(template)
      if (!configResult.success) {
        const firstError = configResult.error.issues[0]
        const errorPath = firstError.path.join('.')
        return {
          success: false,
          error: `${agentContext}: Schema validation failed at ${errorPath}: ${firstError.message}`,
        }
      }
      validatedTemplate = configResult.data
    } else {
      const configResult = DynamicAgentConfigSchema.safeParse(template)
      if (!configResult.success) {
        const firstError = configResult.error.issues[0]
        const errorPath = firstError.path.join('.')
        return {
          success: false,
          error: `${agentContext}: Schema validation failed at ${errorPath}: ${firstError.message}`,
        }
      }
      validatedTemplate = configResult.data
    }

    if (!skipSubagentValidation) {
      const subagentValidation = validateSubagents(
        validatedTemplate.subagents,
        dynamicAgentIds,
      )
      if (!subagentValidation.valid) {
        return {
          success: false,
          error: `${agentContext}: ${formatSubagentError(
            subagentValidation.invalidAgents,
            subagentValidation.availableAgents,
          )}`,
        }
      }
    }

    let inputSchema: AgentTemplate['inputSchema']
    try {
      inputSchema = convertInputSchema(
        validatedTemplate.inputSchema?.prompt,
        validatedTemplate.inputSchema?.params,
        filePath,
      )
    } catch (error) {
      return {
        success: false,
        error: `${agentContext}: ${error instanceof Error ? error.message : 'Schema conversion failed'}`,
      }
    }

    let outputSchema: AgentTemplate['outputSchema']
    if (validatedTemplate.outputSchema) {
      try {
        outputSchema = convertJsonSchemaToZod(validatedTemplate.outputSchema)
      } catch (error) {
        return {
          success: false,
          error: `${agentContext}: Failed to convert outputSchema to Zod: ${error instanceof Error ? error.message : 'Unknown error'}`,
        }
      }
    }

    if (validatedTemplate.handleSteps) {
      if (!isValidGeneratorFunction(validatedTemplate.handleSteps)) {
        return {
          success: false,
          error: `${agentContext}: handleSteps must be a generator function: "function* (params) { ... }". Found: ${validatedTemplate.handleSteps.substring(0, 50)}...`,
        }
      }
    }

    const agentTemplate: AgentTemplate = {
      ...validatedTemplate,
      outputSchema,
      inputSchema,
    }

    return {
      success: true,
      agentTemplate,
    }
  } catch (error) {
    const errorMessage =
      error instanceof Error ? error.message : 'Unknown error'

    const agentId = template?.id || 'unknown'
    const displayName = template?.displayName
    const agentContext = getAgentContext(agentId, displayName)

    return {
      success: false,
      error: `${agentContext}: ${errorMessage}`,
    }
  }
}
